    adminGrantAccess: {
        parameters: {
            query?: never;
            header: {
                /** @description Any value. Proves the request comes from the admin panel's own page. */
                "X-MakonBook-Admin": components["parameters"]["AdminCSRF"];
            };
            path: {
                member_type: "employee" | "teacher";
                /** @description HolliHop employee or teacher id */
                member_id: number;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description Must be false or absent: super admins are made on the server
                     * @constant
                     */
                    super?: false;
                    /** @description May be empty for an editor only */
                    office_ids: number[];
                    /** @description May edit practice tests and questions */
                    editor?: boolean;
                };
            };
        };
        responses: {
            200: components["responses"]["AccessList"];
            400: components["responses"]["Error"];
            401: components["responses"]["Error"];
            /** @description `super_admin_protected` (a super admin, or `super: true`), `forbidden` (not a super admin, or no CSRF header) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description `not_found` — no such employee in HolliHop, or teacher in MakonBook */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description `fired` in HolliHop */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            503: components["responses"]["Error"];
        };
    };
